pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNum, uint256 seed) public {
        // 1. Restrict to admissible domain: timestamp > 0 && blockNum > 0, and ensure blockNum % 15 != 0 to prevent balance drain which would change the contract state beyond our invariant.
        bound(timestamp, 1, type(uint48).max);
        bound(blockNum, 1, type(uint64).max);
        vm.assume(timestamp > 0);
        vm.assume(blockNum % 15 != 0);

        // Set up block environment with fuzzed values
        vm.warp(timestamp);
        vm.roll(blockNum);

        // Fund a caller with exactly 10 ether
        address caller = address(uint160(uint256(keccak256(abi.encode(seed, "caller")))));
        vm.deal(caller, 10 ether);

        // First call should succeed
        vm.prank(caller);
        c.fallback{value: 10 ether}();

        uint256 pastBlockTimeAfterFirst = c.pastBlockTime();

        // Second call in the same block timestamp (no warping)
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        bool secondCallSucceeded = true;
        try c.fallback{value: 10 ether}() {
            secondCallSucceeded = true;
        } catch {
            secondCallSucceeded = false;
        }

        uint256 pastBlockTimeAfterSecond = c.pastBlockTime();

        // Assert: The reference requires that pastBlockTime strictly increases after each successful call.
        // If the second call succeeded, then pastBlockTime must be strictly greater than after the first call.
        // The mutant allows the second call to succeed without updating pastBlockTime, violating this rule.
        assertTrue(!secondCallSucceeded || pastBlockTimeAfterSecond > pastBlockTimeAfterFirst);
    }
}

