pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 extraRolls) public {
        // Keep extra rolls reasonable so the fuzzer can explore sequences within a block
        extraRolls = bound(extraRolls, 0, 50);
        address sender = address(0x1234);
        vm.deal(sender, 1000 ether);

        // First successful call at current timestamp
        vm.prank(sender);
        c.fallback{value: 10 ether}();
        uint256 firstPast = c.pastBlockTime();
        uint256 ts = block.timestamp;

        // Optionally advance blockchain height (roll, not timestamp) to allow more calls without changing timestamp
        vm.roll(block.number + extraRolls);

        // Second call in the same block (same timestamp)
        vm.prank(sender);
        try c.fallback{value: 10 ether}() { } catch { }
        uint256 secondPast = c.pastBlockTime();

        // After any execution, pastBlockTime must equal the timestamp of the LAST successful call.
        // In the reference, the second call reverts, so pastBlockTime stays at firstPast (= ts).
        // In the mutant, the second call succeeds, updating pastBlockTime to ts again but without increase,
        // which still means pastBlockTime equals ts. However, the mutant updates it after a call that should
        // have been blocked, so the property "pastBlockTime equals the block.timestamp of the last successful call"
        // is satisfied by the mutant as well. That's not the right property.
        //
        // Wait — we need a property that DIFFERS. Let's re-read the previous attempts and find a property that
        // actually distinguishes them. If the mutated call succeeds, both firstPast and secondPast equal ts.
        // The invariant should be about the ABILITY to call successfully multiple times, not about the state value.
        // We'll wrap the second call in try/catch and check the boolean `ok`.
    }
}

