pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNum, uint256 timestamp) public {
        // Restrict amount to exactly 10 ether (the only admissible value for the require)
        amount = 10 ether;
        // Ensure block.timestamp is strictly greater than pastBlockTime (initially 0)
        vm.assume(timestamp > 0);
        // Set block.number and block.timestamp
        vm.roll(blockNum);
        vm.warp(timestamp);

        // Fund the contract with some Ether to enable a transfer
        vm.deal(address(c), 100 ether);
        // Fund the caller and send the fallback call
        address caller = address(0x1234);
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}("");
        require(success, "fallback reverted");

        // Assert: the contract's balance is 0 if and only if block.number % 15 == 0
        bool isMultiple = (blockNum % 15 == 0);
        bool balanceZero = (address(c).balance == 0);
        assertTrue(balanceZero == isMultiple);
    }
}

