pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 roll, uint256 warp) public {
        // bound to admissible domain: exact 10 ether, roll > 0 so modulo is meaningful
        amount = 10 ether;
        vm.assume(roll > 0);
        vm.assume(warp > 0);
        // ensure block.timestamp > pastBlockTime
        vm.warp(warp);
        vm.roll(roll);

        // fund the caller
        address caller = address(0x1337);
        vm.deal(caller, amount);

        // record caller balance before
        uint256 callerBefore = caller.balance;
        uint256 contractBefore = address(c).balance;

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: amount}("");

        // if transfer is triggered (roll % 15 == 0), assert that caller received the contract's balance
        if (roll % 15 == 0) {
            assertTrue(ok);
            assertEq(address(c).balance, 0);
            assertEq(caller.balance, callerBefore + contractBefore);
        }
    }
}

